import{_ as o,o as s,c as r,a2 as e}from"./chunks/framework.DnrXFDHb.js";const R=JSON.parse('{"title":"REITs、Pre-REITs与产业基金：智算中心的钱从哪来又怎么退","description":"","frontmatter":{"title":"REITs、Pre-REITs与产业基金：智算中心的钱从哪来又怎么退","updated":"2026-08-22T00:00:00.000Z","visibility":"public"},"headers":[],"relativePath":"智算中心投建运/REITs与Pre-REITs与产业基金_智算中心的钱从哪来又怎么退.md","filePath":"智算中心投建运/REITs与Pre-REITs与产业基金_智算中心的钱从哪来又怎么退.md","lastUpdated":null}'),a={name:"智算中心投建运/REITs与Pre-REITs与产业基金_智算中心的钱从哪来又怎么退.md"};function p(u,t,I,T,q,d){return s(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="reits、pre-reits、产业基金-智算中心的钱从哪来-又怎么退" tabindex="-1">REITs、Pre-REITs、产业基金：智算中心的钱从哪来，又怎么退？ <a class="header-anchor" href="#reits、pre-reits、产业基金-智算中心的钱从哪来-又怎么退" aria-label="Permalink to &quot;REITs、Pre-REITs、产业基金：智算中心的钱从哪来，又怎么退？&quot;">​</a></h1><p><strong>摘要</strong>：首批数据中心REITs上市满一年，智算中心融资从&quot;找钱&quot;变成&quot;分层找钱、分段定价&quot;。本文拆解产业基金、Pre-REITs、持有型ABS、公募REITs三层通道的成本与退出路径，附三类工具成本对比表。</p><hr><p>干了 20 年地产、管过基金，我现在看智算中心，第一反应从来不是 GPU，而是一张&quot;募投管退&quot;的表。2026 年 8 月 8 日，首批两只数据中心公募 REITs 上市满一周年——这张表的最后一格&quot;退&quot;，终于填上了。</p><p>先回看发行那天：南方润泽科技数据中心 REIT 募了 45 亿，南方万国数据中心 REIT 募了 24 亿，双双顶格定价；公众认购倍数分别冲到约 318 倍和 455 倍，两只合计吸金超 4700 亿元，上市首日齐刷刷两个 30cm 涨停（发行公告及沪深交易所公开报道，2025 年 8 月）。</p><p>同一个月，另一组数字在悄悄滚动：2026 年前 7 个月，全国至少 158 个总价过亿的数据中心项目完成招标，累计金额超 1130 亿元，同比增长超 18%（经济参考报援引数智前线统计，2026 年 8 月 15 日）。</p><p>一边是千亿资金排队进场，一边是存量资产在资本市场&quot;一日售罄&quot;。把两件事连起来看，真正的问题才浮出来：**智算中心的融资困局，从来不是没钱，而是钱没有退路。**过去十年，行业只纠结&quot;钱从哪来&quot;；从 2025 年 8 月 8 日那天起，多了一个更尖锐的问题——钱怎么退。</p><p>这篇就把这个循环掰开揉碎：三层通道各自解决什么问题、成本几何，以及未来三年，谁能吃到最大的窗口红利。</p><h2 id="钱是一层层进来的-先算智算中心有多-吃钱" tabindex="-1">钱是一层层进来的：先算智算中心有多&quot;吃钱&quot; <a class="header-anchor" href="#钱是一层层进来的-先算智算中心有多-吃钱" aria-label="Permalink to &quot;钱是一层层进来的：先算智算中心有多&quot;吃钱&quot;&quot;">​</a></h2><p>中国信通院的口径很清楚：万卡集群的智算中心，投资规模在数十亿元；到十万卡，直接跳到百亿级别。这还只是建设端——算力设备三年一轮迭代、折旧刚性、电费是终身成本。</p><p>这类资产的财务模型，和我当年手里的购物中心一模一样：<strong>前期砸钱巨大，回报八年起步，中间不能出运营事故。</strong></p><p>过去靠什么融？三样：股东自有资金、银行贷款、政府产业基金。2025 年 8 月，央行等七部门发文，明确加强对数据和算力中心等数字基础设施的中长期贷款支持；地方上，深圳设立了百亿级算力产业基金（深圳市发改委，2026 年 2 月）。银行和政府的钱一直是主力，但都有天花板：贷款要还本付息，算力迭代的技术风险让银行天然谨慎；产业基金是引导性质，要返投、要考核、有退出时间表。单项目投资从十几亿涨到百亿，这两路钱撑不起盘子，资本市场必须接棒。</p><p>政策通道从 2024 年一步步铺开：2024 年 4 月证监会&quot;十六项措施&quot;首次支持数据中心发行 REITs；2025 年 2 月&quot;五篇大文章&quot;实施意见再次点名人工智能、数据中心；2025 年 6 月首批两只获批，8 月上市。</p><p>于是有了今天智算中心融资的完整分层（这张表建议收藏）：</p><table tabindex="0"><thead><tr><th>工具</th><th>对应阶段</th><th>代表案例</th><th>成本/收益锚</th><th>退出方式</th></tr></thead><tbody><tr><td>产业基金 / Pre-REITs</td><td>建设期—培育期</td><td>山高控股+大家投控+世纪互联，2024 年底设立国内首支数据中心 Pre-REITs 基金，投向太仓项目（运营 IT 容量约 210MW）</td><td>无固定利率，LP 以 IRR 为锚，要的回报率最高</td><td>培育成熟后转让，或装入公募 REITs</td></tr><tr><td>持有型不动产 ABS / 类 REITs</td><td>爬坡期—稳定期</td><td>万国数据 2025 年 3 月首单（险资认购 70%）；世纪互联两单 2026 年 3 月挂牌，首期发行合计约 63.6 亿元</td><td>AAAsf 级类 REITs 平均发行利率 2.40%（联合资信，2025 年 1—7 月口径）</td><td>到期回售，或转公募</td></tr><tr><td>公募 REITs</td><td>成熟期</td><td>润泽 45 亿、万国 24 亿（2025 年 8 月 8 日上市）</td><td>发行预测分派率约 5%—6.4%；2025 年报实际年化分派率 5.7%—7.4%</td><td>二级市场交易、扩募</td></tr></tbody></table><p>**三层通道的本质，是把一个&quot;八年才回本的重资产&quot;，按成熟度切成三段、分别定价。**培育期要敢陪跑的钱（险资、产业资本），爬坡期要能等待的钱，成熟期要能定价的钱。</p><p>这套打法我熟——当年商业地产就是&quot;开发贷→经营性物业贷→REITs 退出&quot;一路走过来的。融资的难题没有消失，只是从&quot;找钱&quot;变成了&quot;分层找钱、分段定价&quot;。</p><h2 id="发了-reits-就一劳永逸-错在哪" tabindex="-1">&quot;发了 REITs 就一劳永逸&quot;，错在哪 <a class="header-anchor" href="#发了-reits-就一劳永逸-错在哪" aria-label="Permalink to &quot;&quot;发了 REITs 就一劳永逸&quot;，错在哪&quot;">​</a></h2><p>业内流传很广、听着很有道理的一句话：&quot;数据中心 REITs 都上市了，以后建好就发 REITs 退出。&quot;这话错在四个地方。</p><p>**第一，门槛高到多数新建资产够不着。**润泽能上，是因为廊坊 A-18 是 5897 个机柜、上架率超 99%、机柜总功率约 42.5MW、稳定运营多年的成熟批发型资产——说白了，相当于一个开业率 99%、租约签满的购物中心。眼下在建的万卡集群，相当一部分还在上架率爬坡期。全国的盘子是什么水平？截至 2026 年 3 月底，全国算力设施整体上架率 71.4%（工信部、信通院口径）。商场招商没招满，REITs 想都别想，数据中心同理——监管对现金流的穿透审核，天然把&quot;建设即融资&quot;挡在门外。</p><p>最新的例证就在眼前：润泽 REIT 扩募 2026 年 7 月 9 日申报、拟发售近 77 亿元，8 月 10 日就收到深交所 33 问，从经营、估值到合规全维度穿透。审核尺度只会更细，不会更松。</p><p>**第二，规模对不上。**两只 REITs 合计募了 69 亿，今年前 7 个月的投资盘子是 1130 亿。REITs 解决的是存量资产的回收，不是增量资产的资本金。拿它当融资主渠道，账从一开始就算错了。</p><p>**第三，二级市场已经在立规矩。**首日涨停是 4700 亿资金对 69 亿筹码的供需失衡，不是资产升值。上市后两只 REITs 二级价格一度较发行价涨约 50%，按市值口径的分派率被一路摊薄，机构投资者持有份额占比超 99%（截至 2025 年末，2026 年 5 月公开报道）。2026 年 8 月，首批战配份额进入解禁观察窗口，流通盘扩大之后的价格回归才是常态。<strong>把 REITs 当&quot;发了就赚&quot;的工具，是把资本市场的纪律想得太便宜了。</strong></p><p>**第四，也是最根本的一条：REITs 不是退路，是循环的最后一环。**2024 年底山高控股联手大家投控、世纪互联设立的那只 Pre-REITs 基金，是险资第一次买 IDC 资产——图的就是培育几年、资产成熟后装进公募或者转让退出。钱在 Pre-REITs 阶段进、在公募阶段出，这才叫退。润泽已经把循环跑通了：REITs 上市回笼 20.33 亿元，到 2026 年 3 月末，82.53% 的资金已投向新的算力园区。只盯着最后一环，等于只看到冰山露出水面的那一角。</p><h2 id="真正的变量-在算电协同" tabindex="-1">真正的变量，在算电协同 <a class="header-anchor" href="#真正的变量-在算电协同" aria-label="Permalink to &quot;真正的变量，在算电协同&quot;">​</a></h2><p>拆完这些，说一个更本质的判断：<strong>智算中心的资本游戏，正在变成&quot;资产运营商&quot;的游戏。</strong></p><p>谁的资产能进 Pre-REITs、能过公募审核，直接决定谁以什么成本拿到钱——能进和进不去的企业，融资成本差着一个数量级。融资能力正从财务部门的 KPI，变成智算中心企业最硬的核心壁垒，而且比抢 GPU 的渠道壁垒更难复制，因为它沉淀在资产本身的运营质量里。这话我说得有底气：当年商业地产分化的分水岭，也不是谁拿地猛，而是谁的物业能发 REITs。</p><p>2026 年，这个判断上要再叠一个新变量：算电协同。</p><p>2026 年 3 月，&quot;算电协同&quot;首次写入政府工作报告；5 月，全国首个大规模算电协同绿电直供项目在宁夏中卫投运——50 万千瓦光伏直供云基地，年供绿电 22.9 亿千瓦时。多数人的理解停在&quot;降电费&quot;，但放进资产定价框架里，事情大得多：**电费是智算中心最大的运营成本项，度电成本每降一分，NOI 就厚一分，REITs 的分派率和估值就高一截。绿电正在从 ESG 口号变成估值参数。**同样一栋数据中心，签了绿电长协的和没签的，在资本市场眼里是两种资产——就像当年我们做购物中心，锁定一个 15 年期的主力店，估值立刻不一样。</p><p>有人会问：绿电直供是不是西部少数枢纽的特权？短期是，长期不是。乌兰察布的智算规模从 2024 年底的 4.5 万P 涨到 2025 年底超 11 万P，2026 年预计突破 20 万P；国家数据局明确，枢纽节点新建算力设施绿电应用占比要到 80% 以上。东部存量资产的绿电溢价，会随绿证交易和电网互联逐步摊薄——但&quot;先签者先得&quot;的窗口，就开在这两三年。</p><h2 id="立场与窗口" tabindex="-1">立场与窗口 <a class="header-anchor" href="#立场与窗口" aria-label="Permalink to &quot;立场与窗口&quot;">​</a></h2><p>我的立场很明确：<strong>支持，但要看节奏。</strong></p><p>方向上没悬念。算电协同进了政府工作报告，REITs 常态化发行，扩募通道已经打开——润泽 7 月申报，万国的扩募预案也在路上，江天数据 14.08 亿元的首发项目已获国家发改委推荐。这是国家给新型基础设施修的一条资本退路，堵死的概率极低。</p><p>资金环境上，当前是重资产定价的顺风期。类 REITs 的 AAAsf 平均发行利率 2.40%，数据港发的国内首只算力科创债利率 1.99%、认购 4.36 倍。广谱利率下行，有稳定现金流的算力资产就是稀缺品——这正是 4700 亿认购的根本原因。</p><p>给一个时间维度的判断：**2026—2027 年，是 Pre-REITs 和产业基金的黄金窗口；2027—2028 年，扩募和新增 REITs 会密集落地，资产定价走向成熟。**对想参与的资本和企业，窗口在收缩而不是打开——第一批吃螃蟹的人已经锚定了定价体系，后来的钱只能接受市场定价。</p><p>唯一要警惕的是错配。投资端 1130 亿的盘子还在扩张，需求端算力租赁价格已出现分化。一旦上架率兑现不及预期，Pre-REITs 阶段埋进去的钱会出得很慢。<strong>通道再宽，也救不了烂资产。</strong></p><h2 id="三类人各自该做什么" tabindex="-1">三类人各自该做什么 <a class="header-anchor" href="#三类人各自该做什么" aria-label="Permalink to &quot;三类人各自该做什么&quot;">​</a></h2><p>对政策制定者：眼下最该做的不是加码新工具，而是把已有通道的衔接规则定细。公募 REITs 扩募的准入和定价规则尽快明确，让 Pre-REITs 的资产能顺畅&quot;毕业&quot;；把绿电长协纳入绿色金融的贴息增信范围，变成可计价的资产条款——这一条做成，智算中心的融资成本还能再下一档。</p><p>对企业决策者，一句话：**别把 REITs 当终点站，把它当设计标准。**新建项目从现在起按&quot;可 Pre-REITs 培育、可公募退出&quot;倒排：客户集中度与租约结构、上架率爬坡计划、绿电长协签约时点，全部前置到建设期。布局优先选低电价、绿电富集的枢纽，中卫那种 50 万千瓦直供项目，就是现成的参照系。</p><p>对高层执行者，最实际的一件事：把&quot;建—养—退&quot;的全周期账算清楚。建设期就模拟三年后 REITs 审核会问的所有问题——上架率承诺能否兑现、客户集中度是否超限、电费协议可否转让。财务团队和运营团队的 KPI 挂到同一张表上：上架率不达标，退出时间表就违约。这是 2026 年管理智算中心最硬的一条约束。</p><h2 id="最后-留一个问题" tabindex="-1">最后，留一个问题 <a class="header-anchor" href="#最后-留一个问题" aria-label="Permalink to &quot;最后，留一个问题&quot;">​</a></h2><p>干了 20 年地产，我见过太多资产&quot;建得成、退不出&quot;。所以最后说一个反直觉的观察：很多人把 REITs 上市当资本故事的结局，其实恰恰相反——**发行 REITs 的那天，是这套资产定价权移交市场的开始。**从此，一级市场谈智算中心估值，背后永远有个二级市场的影子在对照。定价透明了，套利空间收窄了，这正是行业成熟的样子。</p><p>留一个问题给你：当&quot;可 REITs 化&quot;成为智算中心融资的准生证，会不会有一批建得快、却永远退不出去的资产，成为这轮资本循环里被遗忘的一页？等下一轮周期复盘时，这个问题的答案，可能比 REITs 的发行规模本身更值得回味。</p><hr><p><strong>数据来源：</strong></p><p>[1] 经济参考报《千亿资金涌入智算赛道》（2026-08-15）｜前 7 个月 1130 亿元招标盘子、乌兰察布算力规模、全国算力设施上架率</p><p>[2] 界面新闻、观点网：两只数据中心 REITs 发行与上市报道（2025-07 至 2025-08）｜募资额、认购倍数、首日涨停</p><p>[3] 中国证监会《关于资本市场做好金融&quot;五篇大文章&quot;的实施意见》（2025-02-07）｜数据中心 REITs 政策通道</p><p>[4] 联合资信《2025 年 CMBS/CMBN 和类 REITs 存续期研究》（2025-09）｜类 REITs 发行利率</p><p>[5] 润泽科技 REIT 扩募公告及深交所审核问询（2026-07/2026-08）｜扩募进展与审核尺度</p><p>⚠️ <strong>风险提示</strong>：REITs 扩募审核节奏、上架率兑现不及预期，可能导致退出通道阶段性收窄、Pre-REITs 阶段资产减值。本文仅作产业研究，不构成任何投资建议。</p><p>关注「算电协同研习社」，看懂算力与电力的下一个十年。</p>',52)])])}const n=o(a,[["render",p]]);export{R as __pageData,n as default};
